/**
 * Original procedural sample for the web Open example action. This trefoil tube
 * is generated locally; it does not contain or reproduce the desktop dataset.
 * Allocate only when requested and open it through the normal scene controller.
 */
export function createExampleScene(): File {
  const along = 256, around = 16, recordBytes = 32;
  const buffer = new ArrayBuffer(along * around * recordBytes);
  const data = new DataView(buffer);
  const tau = 2 * Math.PI;
  const tilt = 0.6, cosTilt = Math.cos(tilt), sinTilt = Math.sin(tilt);

  for (let ring = 0; ring < along; ring++) {
    const t = tau * ring / along;
    const cos2 = Math.cos(2 * t), sin2 = Math.sin(2 * t);
    const cos3 = Math.cos(3 * t), sin3 = Math.sin(3 * t);
    const radius = (2 + cos3) / 3, radiusDerivative = -sin3;
    const cx = radius * cos2, cy = radius * sin2, cz = sin3 / 3;

    // An orthonormal frame keeps the tube round along the closed centerline.
    let tx = radiusDerivative * cos2 - 2 * radius * sin2;
    let ty = radiusDerivative * sin2 + 2 * radius * cos2;
    let tz = cos3;
    const tangentLength = Math.hypot(tx, ty, tz);
    tx /= tangentLength; ty /= tangentLength; tz /= tangentLength;
    const projection = cos2 * tx + sin2 * ty;
    let nx = cos2 - projection * tx, ny = sin2 - projection * ty;
    let nz = -projection * tz;
    const normalLength = Math.hypot(nx, ny, nz);
    nx /= normalLength; ny /= normalLength; nz /= normalLength;
    const bx = ty * nz - tz * ny, by = tz * nx - tx * nz;
    const bz = tx * ny - ty * nx;

    for (let section = 0; section < around; section++) {
      const v = tau * section / around;
      const normalOffset = 0.075 * Math.cos(v), binormalOffset = 0.075 * Math.sin(v);
      const x = cx + normalOffset * nx + binormalOffset * bx;
      const y = cy + normalOffset * ny + binormalOffset * by;
      const z = cz + normalOffset * nz + binormalOffset * bz;
      const at = (ring * around + section) * recordBytes;
      data.setFloat32(at, x, true);
      data.setFloat32(at + 4, cosTilt * y - sinTilt * z, true);
      data.setFloat32(at + 8, sinTilt * y + cosTilt * z, true);
      for (let axis = 0; axis < 3; axis++) data.setFloat32(at + 12 + 4 * axis, 0.022, true);

      const shade = 0.85 + 0.15 * Math.cos(v - 0.7);
      data.setUint8(at + 24, Math.round((166 + 76 * Math.cos(t)) * shade));
      data.setUint8(at + 25, Math.round((166 + 76 * Math.cos(t - tau / 3)) * shade));
      data.setUint8(at + 26, Math.round((166 + 76 * Math.cos(t + tau / 3)) * shade));
      data.setUint8(at + 27, 255);
      // SPLAT stores wxyz as centered bytes; this normalizes to identity.
      data.setUint8(at + 28, 255);
      data.setUint8(at + 29, 128);
      data.setUint8(at + 30, 128);
      data.setUint8(at + 31, 128);
    }
  }

  return new File([buffer], 'SplatView example.splat', { type: 'application/octet-stream' });
}
